<template>
  <component v-if="modelValue" :is="embedded?'section':ElDialog" :model-value="modelValue" title="权益包配置" width="min(1480px,98vw)" top="2vh" :before-close="close" :close-on-click-modal="false" :show-close="!busy" class="configuration-dialog" data-benefit-configuration-workspace>
    <el-alert v-if="initialError" :title="initialError" type="error" :closable="false"/>
    <template v-else-if="plan&&binding">
      <header class="configuration-heading"><div><strong>{{plan.name||'新建权益包配置'}}</strong><span class="muted">{{readonly?'只读查看':'本次工作草稿尚未生效'}} · {{scopeLabel}}</span></div><el-button v-if="canCreate&&!readonly&&plan.id" data-config-copy @click="copyCurrent">复制后调整</el-button></header>
      <el-alert v-if="notice" :title="notice" type="success" :closable="false" data-config-notice/>
      <el-alert v-if="error" :title="error" type="error" :closable="false" data-config-error/>
      <div class="configuration-grid">
        <nav class="configuration-steps" aria-label="权益包配置步骤"><button v-for="(label,index) in steps" :key="label" type="button" :data-config-step="index" :aria-current="step===index?'step':undefined" @click="step=index"><span>{{index+1}}</span>{{label}}</button></nav>
        <main class="configuration-main">
          <section v-show="step===0" data-config-scope-step>
            <h3>应用到哪里</h3>
            <el-form label-position="top" :disabled="readonly||busy">
              <el-form-item label="配置名称"><el-input v-model="plan.name" aria-label="权益包配置名称" :disabled="!canEditPlan"/></el-form-item>
              <el-form-item label="应用范围"><el-select :model-value="binding.scope.kind" aria-label="配置应用范围类型" :disabled="!canUpdate" @change="changeKind"><el-option value="model" label="商品模型与明确规格"/><el-option value="products" label="明确的 SPU／销售 SKU"/></el-select></el-form-item>
              <template v-if="binding.scope.kind==='model'">
                <el-form-item label="商品模型"><el-select :model-value="binding.scope.modelId" filterable aria-label="配置商品模型" :disabled="!canUpdate" @change="changeModel"><el-option v-for="model in models" :key="model.id" :value="model.id" :label="model.label"/></el-select></el-form-item>
                <el-form-item label="明确版本"><el-select :model-value="binding.scope.versionId||'$draft'" aria-label="配置模型版本" :disabled="!canUpdate" @change="changeVersion"><el-option value="$draft" label="当前模型草稿（仅配置和预览）"/><el-option v-for="version in versions" :key="version.id" :value="version.id" :label="`${version.versionName} · ${version.status==='published'?'已发布':'已下线'}`"/></el-select></el-form-item>
              </template>
              <template v-else>
                <el-form-item label="SPU 商品"><el-select v-model="binding.scope.familyIds" multiple filterable aria-label="配置 SPU 范围" :disabled="!canUpdate"><el-option v-for="family in families" :key="family.id" :value="family.id" :label="`${family.name} · ${family.id}`"/></el-select></el-form-item>
                <el-form-item label="实际销售 SKU"><el-select v-model="binding.scope.skuIds" multiple filterable aria-label="配置 SKU 范围" :disabled="!canUpdate"><el-option v-for="sku in realSkus" :key="sku.id" :value="sku.id" :label="skuLabel(sku.id)"/></el-select></el-form-item>
              </template>
              <el-form-item label="此范围的使用方式"><el-select v-model="binding.mode" aria-label="配置范围使用方式" :disabled="!canUpdate"><el-option v-if="binding.scope.kind==='model'" value="default" label="整个范围使用这一套配置"/><el-option value="replace" label="这个明确范围单独设置"/><el-option value="none" label="这个范围不显示权益包选项"/></el-select></el-form-item>
              <template v-if="binding.scope.kind==='model'&&binding.mode!=='default'"><SalesScopePicker :key="scopeEpoch" ref="scopePicker" v-model="binding.scope.selector" :model-id="binding.scope.modelId" :version-id="binding.scope.versionId" :initial-node-id="binding.scope.nodeId" :initialize-node-selection="false" @validity-change="scopeValid=$event" @pending-change="scopePending=$event"/></template>
              <el-form-item v-if="usages.length" label="继续现有应用范围"><el-select :model-value="binding.id||''" clearable aria-label="继续现有应用范围" @change="selectUsage"><el-option v-for="usage in usages" :key="usage.id" :value="usage.id" :label="`${bindingText(usage)} · ${usage.id}`"/></el-select></el-form-item><el-form-item label="选择已有共享配置"><el-select :model-value="plan.id||'$new'" filterable aria-label="已有权益包配置" @change="choosePlan"><el-option value="$new" label="新建独立配置"/><el-option v-for="item in readablePlans" :key="item.id" :value="item.id" :label="`${item.name} · ${item.id}`"/></el-select></el-form-item>
            </el-form>
            <p v-if="binding.scope.kind==='model'&&!binding.scope.versionId" class="muted">模型草稿可以保存工作输入和模拟，正式应用需要明确的已发布版本。V1 的绑定不会随 V2 自动迁移。</p>
            <p>{{scopePreview.legalCount}} 条合法规格 · {{scopePreview.skuCount}} 条当前真实销售 SKU</p>
            <p v-for="message in scopePreview.issues" :key="message" class="problem">{{message}}</p>
            <details v-if="recoverable.length"><summary>明确恢复其他范围或旧格式工作草稿</summary><article v-for="entry in recoverable" :key="entry.copy.key" class="impact-line"><span>{{entry.copy.planDraft?.name||entry.copy.draft.name||'未命名工作草稿'}} · {{entry.legacy?'旧格式待核对':bindingText(entry.copy.draft)}}</span><el-button :disabled="readonly||busy" link @click="restore(entry.copy)">恢复此草稿</el-button></article></details>
          </section>
          <section v-show="step===1" data-config-items-step><h3>可以选什么</h3><SalesPlanEditor :model-value="true" embedded managed :working-draft="plan" :readonly="readonly||busy"/><p v-if="binding.mode==='none'" class="muted">当前范围不显示权益包选项；项目工作输入仍保留，正式关闭范围不会发布这些输入。</p></section>
          <section v-show="step===2" data-config-compatibility-step>
            <h3>怎样核对兼容性</h3><p class="muted">推荐仅表达搭配建议；正式兼容性仍读取当前设备与商品的真实依据。基本适用与快充分别核对。</p>
            <article v-for="item in plan.items" :key="item.id" class="compatibility-item"><strong>{{item.name||'未命名项目'}}</strong><el-select v-model="item.checkTarget" :disabled="readonly||busy||!canEditPlan||item.scope.kind==='service'" :aria-label="`${item.name||'项目'}兼容性核对对象`"><el-option value="device" label="给本次使用设备配套"/><el-option value="source" label="给当前来源商品配套"/><el-option value="none" label="独立商品或服务"/></el-select><p v-if="item.scope.kind==='service'" class="muted">服务独立计量，不生成商品或兼容声明。</p></article>
            <template v-if="productType&&(!productType.catalogRole||productType.catalogRole==='other')"><el-alert :title="productType.catalogRole==='other'?'产品类型业务用途为其他；不提供主机／配件专用入口。':'产品类型业务用途未指定，不能猜测适用方向。'" type="info" :closable="false"/><el-button v-if="canMaintainType" @click="purposeOpen=true">编辑产品类型业务用途</el-button><p v-else class="muted">当前身份缺少产品类型读取或修改权限。</p></template>
            <p>在右侧选择实际商品并刷新预览，可以定位需要维护兼容性的具体商品。</p>
          </section>
          <section v-show="step===3" data-config-publish-step>
            <h3>预览并发布</h3><p>当前配置被 {{usages.length}} 个明确范围引用。只有本次选中的范围会采用新版本。</p>
            <el-radio-group v-model="publishAction" :disabled="readonly||busy" aria-label="权益包发布动作"><el-radio v-if="canEditPlan&&canPublish&&binding.mode!=='none'" value="publish-only">仅发布新版本</el-radio><el-radio v-if="canEditPlan&&canPublish&&canUpdate&&binding.mode!=='none'" value="publish-apply">发布并应用到所选范围</el-radio><el-radio v-if="plan.publishedVersion&&canPublish&&canUpdate&&binding.mode!=='none'" value="apply-existing">应用已有发布版本</el-radio><el-radio v-if="binding.mode==='none'&&canPublish&&canUpdate" value="disable-range">关闭此范围的权益包选项</el-radio></el-radio-group>
            <el-select v-if="publishAction==='apply-existing'" v-model="existingVersion" aria-label="采用配置发布版本"><el-option v-for="version in plan.versions" :key="version.version" :value="version.version" :label="`配置 v${version.version} · ${version.name}`"/></el-select>
            <p v-if="publishAction!=='publish-only'">当前编辑范围：{{scopeLabel}}</p>
            <details v-if="usages.length" open><summary>共享配置的其他应用范围</summary><el-checkbox-group v-model="selectedBindingIds" :disabled="readonly||busy||publishAction==='publish-only'||binding.mode==='none'"><div v-for="usage in usages.filter(item=>item.id!==binding?.id)" :key="usage.id" class="impact-line"><el-checkbox :value="usage.id">{{bindingText(usage)}} · 当前配置 v{{usage.planVersion}} · {{selectedBindingIds.includes(usage.id)?'本次更新':'保留原版本'}}</el-checkbox></div></el-checkbox-group></details>
            <el-button data-config-review :disabled="busy||scopePending" @click="reviewChange">核对本次影响</el-button>
            <section v-if="review" class="impact-review" data-config-impact><p>{{reviewValid?'当前输入已核对':'输入已有变化，请重新核对。'}}</p><p v-for="message in review.messages" :key="message">{{message}}</p><p>{{review.bindingCount}} 个选中绑定 · {{review.keptCount}} 个相关范围保留原版本</p><p class="muted">仅核对此次范围及当前试选样本，未遍历所有商品组合。已有权益包和历史交付清单不随发布改写。</p><button v-for="problem in review.problems" :key="problem.message" class="problem-link" @click="step=problem.step">{{steps[problem.step]}}：{{problem.message}}</button></section>
            <p v-if="!canPublish" class="muted">当前身份没有权益包配置发布权限，可以查看允许读取的内容{{canEditPlan?'或保存工作草稿':''}}。</p>
          </section>
        </main>
        <aside class="configuration-preview" data-config-preview>
          <h3>当前效果</h3><el-radio-group v-model="previewMode" size="small" aria-label="配置效果模式" @change="resetSimulation"><el-radio-button value="effective">当前已生效</el-radio-button><el-radio-button value="draft">本次草稿模拟</el-radio-button></el-radio-group>
          <p class="muted">{{previewMode==='draft'?'尚未生效；模拟不会创建权益包、发布版本或交付记录。':'读取正式配置与正式兼容性依据。'}}</p>
          <el-select v-model="sourceSkuId" filterable clearable aria-label="配置试选来源 SKU" placeholder="选择当前范围内的真实销售 SKU" @change="resetSimulation"><el-option v-for="sku in sampleSkus" :key="sku.id" :value="sku.id" :label="skuLabel(sku.id)"/></el-select>
          <el-select v-model="deviceSkuId" filterable clearable aria-label="配置试选使用设备" placeholder="本次使用设备（主机来源可留空）" @change="resetSimulation"><el-option v-for="sku in devices" :key="sku.id" :value="sku.id" :label="skuLabel(sku.id)"/></el-select>
          <el-button data-config-refresh-preview :disabled="!canReadPreview||busy" @click="refreshPreview">刷新实际效果</el-button>
          <p v-if="!canReadPreview" class="muted">查看实际试选需商品、规划与兼容性读取权限。</p><p v-else-if="!sampleSkus.length" class="muted">可查看配置范围，暂不能进行实际商品试选。</p>
          <template v-if="simulation"><p data-config-preview-version>{{simulation.versionLabel}}</p><p v-if="previewStale" class="problem">输入已有变化，当前为上次结果，请刷新。</p><p v-for="message in simulation.issues" :key="message" class="problem">{{message}}</p><p v-if="simulation.query.resolution.message" class="muted">{{simulation.query.resolution.message}}</p>
            <article v-for="row in simulation.query.rows" :key="row.key" class="preview-candidate" :data-config-candidate="row.key" :data-status="row.status"><strong>{{row.summary?.name||row.item.name}}</strong><small>{{row.item.name}} · {{candidateState(row)}}</small><p>{{row.reason}}</p><div><el-button size="small" :disabled="!row.canAdd||!simulation.canPreview" @click="tryAdd(row)">模拟加入</el-button><el-button v-if="row.skuId&&row.status!=='not-required'" size="small" link :disabled="!canMaintainCompatibility" @click="maintainCompatibility(row)">维护兼容性</el-button></div><details><summary>来源与版本</summary><p>{{row.evidence}} · {{row.plan?.planId?.startsWith('preview:')?'本次未发布模拟':`配置 v${row.plan?.version||'—'}`}}</p></details></article>
            <p v-if="!simulation.query.rows.length" class="muted">此样本当前没有可选项目；请核对范围或兼容性资料。</p>
            <details v-if="simulation.query.excludedRows.length"><summary>未进入正常候选的商品（{{simulation.query.excludedRows.length}}）</summary><p v-for="row in simulation.query.excludedRows" :key="row.key">{{row.summary?.name||row.item.name}}：{{row.reason}}</p></details>
            <section v-if="selection.goods.length||selection.services.length" data-config-simulated-selection><h4>模拟清单</h4><div v-for="line in selection.goods" :key="line.id" class="simulation-line"><span>{{line.snapshot.name}}</span><el-input-number :model-value="line.quantity" :min="1" :max="9999" :aria-label="`${line.snapshot.name}模拟数量`" @change="(value:number|undefined)=>changeQuantity(line.id,Number(value))"/><el-button link @click="removeSimulation(line.id)">移除</el-button></div><div v-for="line in selection.services" :key="line.id" class="simulation-line"><span>{{line.name}}</span><el-input-number :model-value="line.quantity" :min="1" :max="9999" :aria-label="`${line.name}模拟数量`" @change="(value:number|undefined)=>changeQuantity(line.id,Number(value))"/><el-button link @click="removeSimulation(line.id)">移除</el-button></div></section>
            <details v-if="simulation.validation.issues.length"><summary>必选、数量及依赖核对</summary><p v-for="issue in simulation.validation.issues" :key="issue.code+issue.message" :class="issue.severity==='error'?'problem':'muted'">{{issue.message}}</p></details>
          </template>
          <p v-if="!canMaintainCompatibility" class="muted">维护兼容性需要相应新增或修改权限；试选不要求这些修改权限。</p>
        </aside>
      </div>
      <footer class="configuration-actions"><span class="muted">{{dirty?'有未保存工作输入':'当前工作输入已保存'}} · {{scopePreview.legalCount}} 合法规格 / {{scopePreview.skuCount}} 真实 SKU</span><el-button :disabled="busy" @click="close()">返回</el-button><el-button v-if="!readonly&&(canEditPlan||canUpdate)" data-config-save-working :loading="busy" @click="saveWorking">保存工作草稿</el-button><el-button v-if="!readonly&&canSubmit&&reviewValid&&!review?.problems.length" type="primary" data-config-confirm-publish :loading="busy" @click="commit">{{publishAction==='publish-only'?'确认发布新版本':publishAction==='apply-existing'?'确认应用已有版本':publishAction==='disable-range'?'确认关闭此范围选项':'确认发布并应用'}}</el-button><el-button v-else-if="!readonly&&canSubmit" type="primary" :disabled="busy" @click="step=3;reviewChange()">检查并发布</el-button></footer>
    </template>
    <ProductTypePurposeEditor v-if="purposeOpen&&productType" ref="purposeEditor" v-model:open="purposeOpen" :type-id="productType.id"/>
  </component>
</template>
<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {ElDialog,ElMessageBox} from 'element-plus'
import {onBeforeRouteLeave,onBeforeRouteUpdate,useRouter} from 'vue-router'
import {useCatalogStore,uid} from '../../stores/catalog'
import {isRealSku} from '../../domain/catalogIdentity'
import {compatibilityRecordRole} from '../../domain/deviceResolution'
import {savedSkuName,savedSkuCode} from '../../domain/productList'
import {cloneSales,planProblems,previewSalesBinding,salesBindingContext,salesSignature} from '../../domain/salesConfiguration'
import {salesConfigurationCommitBasis,type SalesConfigurationCommit} from '../../domain/salesConfigurationCommands'
import {salesBindingWorkingIdentity,salesBindingWorkingTaskKey,type SalesBindingWorkingCopy} from '../../domain/salesBindingWorkingCopy'
import {previewSalesConfigurationScope,previewSalesConfiguration,createSalesConfigurationPreviewData,addSalesPreviewCandidate,removeSalesPreviewPosition} from '../../domain/salesConfigurationPreview'
import {newBenefitPackageDraft,setBenefitPositionQuantity} from '../../domain/benefitPackages'
import {selectorForNode} from '../../domain/templateCompatibility'
import {templateProductType} from '../../domain/templateHostCompatibility'
import type {SalesCandidate,SalesOptionBinding,SalesOptionPlan} from '../../domain/salesConfigurationTypes'
import type {TemplateSpecSelector} from '../../domain/templateCompatibilityTypes'
import SalesPlanEditor from './SalesPlanEditor.vue'
import SalesScopePicker from './SalesScopePicker.vue'
import ProductTypePurposeEditor from '../catalog-workspace/ProductTypePurposeEditor.vue'
const props=defineProps<{modelValue:boolean;planId?:string;bindingId?:string;copyId?:string;modelId?:string;versionId?:string|null;nodeId?:string;entryNodeId?:string;selector?:TemplateSpecSelector;initialBinding?:SalesOptionBinding;readonly?:boolean;embedded?:boolean;resumeToken?:string}>()
const emit=defineEmits<{'update:modelValue':[boolean];saved:[string,string?]}>()
const store=useCatalogStore(),router=useRouter(),plan=ref<SalesOptionPlan>(),binding=ref<SalesOptionBinding>(),step=ref(0),busy=ref(false),error=ref(''),notice=ref(''),initialError=ref(''),baseline=ref(''),scopeEpoch=ref(0),scopePending=ref(false),scopeValid=ref(true)
const steps=['应用到哪里','可以选什么','怎样核对兼容性','预览并发布']
const scopePicker=ref<InstanceType<typeof SalesScopePicker>>(),purposeEditor=ref<InstanceType<typeof ProductTypePurposeEditor>>(),purposeOpen=ref(false)
const previewMode=ref<'draft'|'effective'>('draft'),sourceSkuId=ref(''),deviceSkuId=ref(''),selection=ref(newBenefitPackageDraft()),simulation=ref<ReturnType<typeof previewSalesConfiguration>>(),previewSignature=ref('')
const selectedBindingIds=ref<string[]>([]),existingVersion=ref<number>(),publishAction=ref<'publish-only'|'publish-apply'|'apply-existing'|'disable-range'>('publish-apply')
type Review={signature:string;basis:string;messages:string[];problems:{step:number;message:string}[];bindingCount:number;keptCount:number;bindings:SalesOptionBinding[]}
const review=ref<Review>(),workingRevisions=new Map<string,number>()
let alive=true,epoch=0,taskId=uid('configuration-task'),expectedPlanRevision=0,request={signature:'',id:''},resumeToken=props.resumeToken||uid('configuration-return')
const canCreate=computed(()=>store.can('product:sales-config:create')),canUpdate=computed(()=>store.can('product:sales-config:update')),canPublish=computed(()=>store.can('product:sales-config:publish'))
const canEditPlan=computed(()=>!props.readonly&&store.can(plan.value?.id?'product:sales-config:update':'product:sales-config:create'))
const canSubmit=computed(()=>canPublish.value&&(canEditPlan.value||canUpdate.value&&(publishAction.value==='apply-existing'||publishAction.value==='disable-range')))
const canReadPreview=computed(()=>store.can('product:sku:read')&&store.can('product:compatibility:read')&&store.can('product:planning:read'))
const canMaintainCompatibility=computed(()=>!props.readonly&&canReadPreview.value&&(store.can('product:compatibility:create')||store.can('product:compatibility:update')))
const productType=computed(()=>binding.value?.scope.kind==='model'?templateProductType(store.data,binding.value.scope.modelId):undefined)
const canMaintainType=computed(()=>!props.readonly&&store.can('product:type:read')&&store.can('product:type:update'))
const realSkus=computed(()=>store.can('product:sku:read')?store.data.skus.filter(sku=>isRealSku(store.data,sku)):[])
const families=computed(()=>store.can('product:spu:read')?store.data.families.filter(family=>realSkus.value.some(sku=>sku.familyId===family.id)):[])
const models=computed(()=>store.can('product:model:read')?store.data.specCanvases.map(model=>({id:model.templateId,label:`${model.name||model.templateId} · ${model.templateId}`})):[])
const versions=computed(()=>binding.value?.scope.kind==='model'?store.data.specModelVersions.filter(version=>version.templateId===(binding.value!.scope as {modelId:string}).modelId):[])
const readablePlans=computed(()=>(store.data.salesOptionPlans||[]).filter(item=>item.schemaVersion===1))
const usages=computed(()=>(store.data.salesOptionBindings||[]).filter(item=>item.schemaVersion===1&&item.planId===plan.value?.id))
const hasScope=computed(()=>!!binding.value&&(binding.value.scope.kind==='model'?!!binding.value.scope.modelId:!!(binding.value.scope.familyIds.length||binding.value.scope.skuIds.length)))
const scopePreview=computed(()=>binding.value?previewSalesConfigurationScope(store.data,binding.value):{legalCount:0,skuCount:0,skuIds:[],issues:[],unresolved:[],canApply:false,draftOnly:false,stamp:'',samples:[]})
const scopeLabel=computed(()=>binding.value?bindingText(binding.value):'尚未选择范围')
const sampleSkus=computed(()=>canReadPreview.value?realSkus.value.filter(sku=>scopePreview.value.skuIds.includes(sku.id)):[])
const devices=computed(()=>canReadPreview.value?realSkus.value.filter(sku=>compatibilityRecordRole(store.data,sku.id)==='host'):[])
const recoverable=computed(()=>store.listSalesBindingWorkingCopies().copies.filter(entry=>entry.copy.planDraft?.id&&entry.copy.planDraft.id===plan.value?.id||binding.value?.scope.kind==='model'&&entry.copy.draft.scope.kind==='model'&&entry.copy.draft.scope.modelId===binding.value.scope.modelId))
const currentInput=()=>salesSignature([plan.value,binding.value,selectedBindingIds.value,publishAction.value,existingVersion.value])
const dirty=computed(()=>!!plan.value&&currentInput()!==baseline.value||scopePending.value)
const reviewValid=computed(()=>!!review.value&&review.value.signature===currentInput()&&!scopePending.value)
const previewStale=computed(()=>!!simulation.value&&previewSignature.value!==currentInput())
function emptyPlan():SalesOptionPlan{return {schemaVersion:1,id:'',name:'',revision:0,status:'draft',items:[],rules:[],publishedVersion:null,versions:[],createdAt:'',updatedAt:''}}
function emptyBinding():SalesOptionBinding{return {schemaVersion:1,id:'',revision:0,name:'权益包应用范围',enabled:true,scope:{kind:'products',familyIds:[],skuIds:[]},mode:'replace',planId:null,planVersion:null,source:'权益包管理员配置',updatedAt:''}}
function skuLabel(id:string){const sku=store.data.skus.find(item=>item.id===id);return sku?`${savedSkuName(sku)} · ${savedSkuCode(sku)||sku.id}`:`商品已失效 · ${id}`}
